import { getDeepSignalRootId, getDeepSignalVersion, isDeepSignal, subscribeDeepMutations, } from "./deepSignal.js";
/**
 * Watch for changes to a deepSignal.
 *
 * Whenever a change is made, `callback` is called with the patches describing the change and the new value.
 * If you set `triggerInstantly`, the callback is called on every property change.
 * If not, all changes are aggregated and `callback` is called in a microtask when
 * the current task finishes, e.g. `await` is called (meaning it supports batching).
 *
 * When objects are added to Sets, their **synthetic ID (usually `@id`) becomes part of the patch path**. This allows patches to uniquely identify which Set entry is being mutated.
 *
 * When you do not need need the patches but only want to be called back on object changes that you depend on, you are advised to use {@link effect} instead.
 *
 * Note: If you attach an existing signal object, you won't see the changes made on the child signal object by watching the root.
 * All you will see is an initial `add` patch with the signal object as `value`. Watch the nested object separately.
 *
 * @example
 * ```ts
 * const state = deepSignal(
 *     { s: new Set() },
 *     { ...}
 * );
 *
 * watch(state, ({ patches }) => {
 *     console.log(JSON.stringify(patches));
 * });
 *
 * state.s.add({ data: "test" });
 * // Will log:
 * // [
 * //   {"path":["s","did:ng:o:123"],"op":"add"},
 * //   {"path":["s","did:ng:o:123","@id"],"op":"add","value":"did:ng:o:123"},
 * //   {"path":["s","did:ng:o:123","data"],"op":"add","value":"test"}
 * // ]
 *
 * state.s.getById("did:ng:o:123")!.data = "new value"
 * // Will log:
 * // [
 * //   {"path":["s","did:ng:o:123","data"],"op":"add","value":"new value"}
 * // ]
 * ```
 */
export function watch(source, callback, options = {}) {
    if (!isDeepSignal(source)) {
        throw new Error("watch() expects a deepSignal root proxy");
    }
    const rootId = getDeepSignalRootId(source);
    if (!rootId)
        throw new Error("Unable to resolve deepSignal root id");
    let active = true;
    let cleanup;
    const { immediate, once } = options;
    const registerCleanup = (fn) => {
        cleanup = fn;
    };
    const runCleanup = () => {
        if (!cleanup)
            return;
        try {
            cleanup();
        }
        finally {
            cleanup = undefined;
        }
    };
    const stopListening = () => {
        if (!active)
            return;
        active = false;
        runCleanup();
        unsubscribe();
    };
    const deliver = (batch) => {
        if (!active)
            return;
        runCleanup();
        const next = source;
        callback({
            patches: batch.patches,
            version: batch.version,
            newValue: next,
        });
        if (once)
            stopListening();
    };
    const unsubscribe = subscribeDeepMutations(rootId, (batch) => {
        if (!batch.patches.length)
            return;
        deliver(batch);
    }, options.triggerInstantly);
    if (immediate) {
        deliver({
            patches: [],
            version: getDeepSignalVersion(rootId) ?? 0,
        });
    }
    return {
        stopListening,
        registerCleanup,
    };
}
